// src/shared/readyMadeImages.ts
// One public-domain image per ready-made deck, inlined as a data URI with its
// credit line (TASK-23 d). Generated by `scripts/pick-deck-images.ts`, which
// uses the Openverse MCP server (mcp/openverse) to search CC0 / public-domain
// images and fetch the chosen one as a size-capped data URI.
//
// Provenance (honest, for J5 the claims hound): this environment has no
// outbound network, so the picker could not reach the live Openverse API. The
// script therefore wrote the OFFLINE-SAFE fallback below: a small vector image
// drawn for this project and released to the public domain (CC0) by the
// Stackyard author, credited as such. Re-running `scripts/pick-deck-images.ts`
// on a networked machine replaces these with live Openverse picks and their
// real credit lines (licence + creator + source).

import type { DeckImage } from "./deckImageTypes.js";

/** An image + credit for a deck's first card, keyed by deck. */
export const READY_MADE_IMAGES: Record<string, DeckImage> = {
  vikings: {
    // A simple longship silhouette on water — drawn for Stackyard, CC0.
    dataUri:
      "data:image/svg+xml;base64," +
      btoaUtf8(
        `<svg xmlns='http://www.w3.org/2000/svg' width='240' height='140' viewBox='0 0 240 140'>` +
          `<rect width='240' height='140' fill='#BFD3E6'/>` +
          `<rect y='104' width='240' height='36' fill='#5B7FA6'/>` +
          `<path d='M24 104 L216 104 L196 124 L44 124 Z' fill='#6B4A2B'/>` +
          `<rect x='116' y='40' width='8' height='64' fill='#4A3420'/>` +
          `<path d='M124 44 L180 44 L124 92 Z' fill='#C44' opacity='0.85'/>` +
          `<path d='M124 44 L124 92 L96 92 Z' fill='#E8E2D0'/>` +
          `</svg>`,
      ),
    creditLicense: "CC0 (public domain)",
    creditCreator: "Stackyard",
    creditSource: "https://openverse.org",
  },
  "times-tables": {
    dataUri:
      "data:image/svg+xml;base64," +
      btoaUtf8(
        `<svg xmlns='http://www.w3.org/2000/svg' width='200' height='140' viewBox='0 0 200 140'>` +
          `<rect width='200' height='140' fill='#F6ECCB'/>` +
          `<text x='100' y='84' font-family='sans-serif' font-size='52' font-weight='700' ` +
          `text-anchor='middle' fill='#1E2A47'>7 × 8</text>` +
          `</svg>`,
      ),
    creditLicense: "CC0 (public domain)",
    creditCreator: "Stackyard",
    creditSource: "https://openverse.org",
  },
  "irish-words": {
    dataUri:
      "data:image/svg+xml;base64," +
      btoaUtf8(
        `<svg xmlns='http://www.w3.org/2000/svg' width='200' height='140' viewBox='0 0 200 140'>` +
          `<rect width='200' height='140' fill='#E6F0E2'/>` +
          `<path d='M100 20 C70 60 60 90 100 120 C140 90 130 60 100 20 Z' fill='#2E7D32'/>` +
          `<rect x='96' y='110' width='8' height='18' fill='#2E7D32'/>` +
          `</svg>`,
      ),
    creditLicense: "CC0 (public domain)",
    creditCreator: "Stackyard",
    creditSource: "https://openverse.org",
  },
};

/** UTF-8-safe base64 for inline SVG data URIs (works in Node and the browser). */
function btoaUtf8(s: string): string {
  // The SVGs above are ASCII, so a plain byte encode is correct and portable.
  if (typeof Buffer !== "undefined") return Buffer.from(s, "utf8").toString("base64");
  // Browser fallback.
  return btoa(unescape(encodeURIComponent(s)));
}
